import React, { useState } from 'react';
import emailjs from 'emailjs-com';
import { useTranslation } from 'gatsby-plugin-react-i18next';
import styles from "../styles/pagesStyles";

const EmailForm = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: ''
  });
  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [successMessage, setSuccessMessage] = useState(false);
  const { t } = useTranslation();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>): void => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });

      // Clear the error message when the field becomes valid
      setErrors((prevErrors) => ({
        ...prevErrors,
        [name]: ''
      }));
  };

  const validateForm = () => {
    const newErrors: { [key: string]: string } = {};
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phoneRegex = /^\+?[0-9\s-]{7,15}$/;

    if (!formData.name) newErrors.name = t("contact.form.error.name");
    if (!formData.email || !emailRegex.test(formData.email)) newErrors.email = t("contact.form.error.email");
    if (!formData.phone || !phoneRegex.test(formData.phone)) newErrors.phone = t("contact.form.error.phone");
    if (!formData.message) newErrors.message = t("contact.form.error.message");

    setErrors(newErrors);

    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>): void => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    emailjs.send(
      'service_7wo3z7r', // Service ID Codecrafted Studios
      'template_pnjdd6d', // Template ID
      formData,
      'mF_DgvHzKjt2tKkrM' // UserID Codecrafted Studios
    ).then(
      () => {
        setSuccessMessage(true);
        setFormData({ name: '', email: '', phone: '', message: '' });
        setErrors({});
      },
      (error: { text: string }) => {
        console.error(error.text);
      }
    );
  };

  if (successMessage) {
    return (
      <div className="text-center p-6">
        <h2 className="text-2xl font-semibold text-success">{t("contact.form.success")}</h2>
        <button
          onClick={() => setSuccessMessage(false)}
          className={styles.button}
        >
          {t("contact.form.back") || "Return to Home"}
        </button>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col space-y-4">
      <input
        type="text"
        name="name"
        placeholder={t("contact.form.name") || "Name"}
        value={formData.name}
        onChange={handleChange}
        className={styles.input}
      />
      {errors.name && <p className="text-error text-shadow">{errors.name}</p>}

      <input
        type="email"
        name="email"
        placeholder={t("contact.form.email") || "Email"}
        value={formData.email}
        onChange={handleChange}
        className={styles.input}
      />
      {errors.email && <p className="text-error text-shadow">{errors.email}</p>}

      <input
        type="tel"
        name="phone"
        placeholder={t("contact.form.phone") || "Phone"}
        value={formData.phone}
        onChange={handleChange}
        className={styles.input}
      />
      {errors.phone && <p className="text-error text-shadow">{errors.phone}</p>}

      <textarea
        name="message"
        placeholder={t("contact.form.message") || "Message"}
        value={formData.message}
        onChange={handleChange}
        className={styles.input}
      />
      {errors.message && <p className="text-error text-shadow">{errors.message}</p>}

      <button type="submit" className={styles.button}>{t("contact.form.button") || "Send"}</button>
    </form>
  );
};

export default EmailForm;

